package com.classvoice.controller; import com.classvoice.dao.*; import com.classvoice.model.User; import com.classvoice.util.WebUtil; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.IOException; import java.util.*;
@WebServlet("/teacher/keyword/add") public class AddKeywordServlet extends HttpServlet {protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{long lid=WebUtil.longParam(r,"lectureId"),tid=WebUtil.longParam(r,"topicId");try{User u=(User)r.getSession().getAttribute("user");LectureDAO ld=new LectureDAO();TopicDAO td=new TopicDAO();if(lid<1||tid<1||!ld.belongsToTeacher(lid,u.getUserId())||!td.belongsToLecture(tid,lid)){p.sendError(404);return;}String raw=WebUtil.trim(r.getParameter("keywords"));if(raw.isBlank()){r.getSession().setAttribute("flashError","Enter at least one keyword.");}else{KeywordDAO kd=new KeywordDAO();for(String part:raw.split(",")){String k=part.trim();if(!k.isBlank()&&k.length()<=100)kd.add(tid,k);}r.getSession().setAttribute("flash","Keyword(s) added.");}p.sendRedirect(r.getContextPath()+"/teacher/topics?lectureId="+lid);}catch(Exception e){throw new ServletException(e);}}}
